CREATE TABLE "FinanceConfig" ("id" TEXT NOT NULL PRIMARY KEY, "payload" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "FinanceRecord" ("id" TEXT NOT NULL PRIMARY KEY, "kind" TEXT NOT NULL, "payload" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "FinanceRecord_kind_createdAt_idx" ON "FinanceRecord"("kind", "createdAt");
CREATE TABLE "FinanceAttachment" ("id" TEXT NOT NULL PRIMARY KEY, "metadata" TEXT NOT NULL, "data" BLOB NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "FinanceAudit" ("id" TEXT NOT NULL PRIMARY KEY, "actorId" TEXT NOT NULL, "operation" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
